import * as React from "react";
import {
  Dialog as D,
  AlertDialog as A,
  Popover as P,
  Tooltip as T,
  HoverCard as H,
  Toast as RT,
} from "radix-ui";
import { X } from "lucide-react";
import { Button } from "./button";
import { cx } from "./utils";
type ModalProps = {
  trigger?: React.ReactElement;
  title: string;
  description: string;
  children: React.ReactNode;
  open?: boolean;
  onOpenChange?: (v: boolean) => void;
  footer?: React.ReactNode;
  placement?: "center" | "right" | "bottom";
};
export function Modal({
  trigger,
  title,
  description,
  children,
  open,
  onOpenChange,
  footer,
  placement = "center",
}: ModalProps) {
  const previousFocus = React.useRef<HTMLElement | null>(null);
  return (
    <D.Root open={open} onOpenChange={onOpenChange}>
      {trigger && <D.Trigger asChild>{trigger}</D.Trigger>}
      <D.Portal>
        <D.Overlay className="a-overlay" />
        <D.Content
          onOpenAutoFocus={() => {
            previousFocus.current = document.activeElement instanceof HTMLElement
              ? document.activeElement
              : null;
          }}
          onCloseAutoFocus={(event) => {
            if (!trigger && previousFocus.current?.isConnected) {
              event.preventDefault();
              previousFocus.current.focus({ preventScroll: true });
            }
          }}
          className={cx(
            "a-modal-content fixed z-50 flex max-h-[90dvh] flex-col border border-line bg-card text-ink shadow-xl outline-none",
            placement === "center"
              ? "left-1/2 top-1/2 w-[min(560px,calc(100%-32px))] -translate-x-1/2 -translate-y-1/2 rounded-2xl"
              : placement === "right"
                ? "right-0 top-0 h-dvh max-h-dvh w-[min(460px,100%)]"
                : "bottom-0 left-0 right-0 max-h-[85dvh] rounded-t-2xl",
          )}
        >
          <div className="border-b border-line px-6 py-5 pe-14">
            <D.Title className="font-editorial text-2xl">{title}</D.Title>
            <D.Description className="mt-2 text-sm text-muted">
              {description}
            </D.Description>
          </div>
          <div className="min-h-0 overflow-y-auto overscroll-contain p-5 sm:p-6">{children}</div>
          {footer && (
            <div className="flex flex-wrap justify-end gap-3 border-t border-line p-5">
              {footer}
            </div>
          )}
          <D.Close
            aria-label="Close dialog"
            className="a-close absolute end-3 top-3 flex size-11 items-center justify-center rounded-md hover:bg-surface"
          >
            <X className="size-4" />
          </D.Close>
        </D.Content>
      </D.Portal>
    </D.Root>
  );
}
export const Dialog = Modal;
export function Sheet(props: Omit<ModalProps, "placement">) {
  return <Modal {...props} placement="right" />;
}
export function Drawer(props: Omit<ModalProps, "placement">) {
  return <Modal {...props} placement="bottom" />;
}
export type AlertDialogProps = {
  trigger?: React.ReactElement;
  title: string;
  description: React.ReactNode;
  /** Return a promise to keep the dialog open with a pending confirmation. A rejection shows its message and allows a retry. */
  onConfirm: () => void | Promise<unknown>;
  confirmLabel?: string;
  cancelLabel?: string;
  /** danger marks an irreversible action; neutral asks for a decision. */
  tone?: "danger" | "neutral";
  /** Short eyebrow above the title. Defaults to the tone's wording; pass an empty string to hide it. */
  label?: string;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Optional detail between the description and the actions, such as what will be affected. */
  children?: React.ReactNode;
};
export function AlertDialog({
  trigger,
  title,
  description,
  onConfirm,
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  tone = "danger",
  label = tone === "danger" ? "Irreversible action" : "Before you continue",
  open,
  onOpenChange,
  children,
}: AlertDialogProps) {
  const [internalOpen, setInternalOpen] = React.useState(false);
  const [pending, setPending] = React.useState(false);
  const [error, setError] = React.useState("");
  const isOpen = open ?? internalOpen;
  const errorId = React.useId();
  const setOpen = (next: boolean) => {
    if (!next && pending) return;
    if (!next) setError("");
    setInternalOpen(next);
    onOpenChange?.(next);
  };
  const confirm = async (event: React.MouseEvent) => {
    event.preventDefault();
    setError("");
    try {
      setPending(true);
      await onConfirm();
      setPending(false);
      setInternalOpen(false);
      onOpenChange?.(false);
    } catch (reason) {
      setPending(false);
      setError(
        reason instanceof Error && reason.message
          ? reason.message
          : "Something went wrong. Try again.",
      );
    }
  };
  return (
    <A.Root open={isOpen} onOpenChange={setOpen}>
      {trigger && <A.Trigger asChild>{trigger}</A.Trigger>}
      <A.Portal>
        <A.Overlay className="a-overlay" />
        <A.Content
          onEscapeKeyDown={(event) => {
            if (pending) event.preventDefault();
          }}
          className="a-modal-content a-alert fixed left-1/2 top-1/2 z-50 flex max-h-[90dvh] w-[min(460px,calc(100%-32px))] -translate-x-1/2 -translate-y-1/2 flex-col overflow-y-auto rounded-2xl border border-line bg-card text-ink shadow-xl outline-none"
        >
          <div className="px-6 pt-6 sm:px-7 sm:pt-7">
            {label && (
              <p
                aria-hidden="true"
                className={cx(
                  "mb-3 text-[0.6875rem] font-medium uppercase tracking-[0.12em]",
                  tone === "danger" ? "text-danger" : "text-muted",
                )}
              >
                {label}
              </p>
            )}
            <A.Title className="font-editorial text-[1.625rem] leading-tight tracking-tight sm:text-[1.75rem]">
              {title}
            </A.Title>
            <A.Description className="mt-3 max-w-prose text-[0.9375rem] leading-relaxed text-muted">
              {description}
            </A.Description>
            {children && <div className="mt-4 text-sm leading-relaxed">{children}</div>}
            {error && (
              <p
                id={errorId}
                role="alert"
                className="mt-4 rounded-lg border border-danger/30 bg-danger/5 px-3 py-2 text-sm leading-relaxed text-danger"
              >
                {error}
              </p>
            )}
          </div>
          <div className="mx-6 mt-6 border-t border-line sm:mx-7" />
          <div className="flex flex-col-reverse gap-2 px-6 py-5 sm:flex-row sm:justify-end sm:gap-3 sm:px-7">
            <A.Cancel asChild>
              <Button tone="outline" disabled={pending} className="w-full sm:w-auto">
                {cancelLabel}
              </Button>
            </A.Cancel>
            <A.Action asChild>
              <Button
                tone={tone === "danger" ? "danger" : "primary"}
                loading={pending}
                aria-describedby={error ? errorId : undefined}
                onClick={confirm}
                className="w-full sm:w-auto"
              >
                {confirmLabel}
              </Button>
            </A.Action>
          </div>
        </A.Content>
      </A.Portal>
    </A.Root>
  );
}
export function Popover({
  trigger,
  children,
  label,
}: {
  trigger: React.ReactElement;
  children: React.ReactNode;
  label: string;
}) {
  return (
    <P.Root>
      <P.Trigger asChild>{trigger}</P.Trigger>
      <P.Portal>
        <P.Content
          aria-label={label}
          sideOffset={8}
          className="a-popup w-72 p-5"
        >
          {children}
          <P.Close
            aria-label="Close popover"
            className="absolute end-1 top-1 p-1"
          >
            <X className="size-3" />
          </P.Close>
        </P.Content>
      </P.Portal>
    </P.Root>
  );
}
export function Tooltip({
  children,
  content,
}: {
  children: React.ReactElement;
  content: string;
}) {
  return (
    <T.Provider delayDuration={250}>
      <T.Root>
        <T.Trigger asChild>{children}</T.Trigger>
        <T.Portal>
          <T.Content
            sideOffset={6}
            className="a-tooltip z-[60] rounded-md bg-ink px-3 py-2 text-xs text-paper"
          >
            {content}
            <T.Arrow className="fill-ink" />
          </T.Content>
        </T.Portal>
      </T.Root>
    </T.Provider>
  );
}
export function HoverCard({
  trigger,
  children,
}: {
  trigger: React.ReactElement;
  children: React.ReactNode;
}) {
  return (
    <H.Root>
      <H.Trigger asChild>{trigger}</H.Trigger>
      <H.Portal>
        <H.Content sideOffset={8} className="a-popup w-72 p-5">
          {children}
        </H.Content>
      </H.Portal>
    </H.Root>
  );
}
export function Toast({open,onOpenChange,title,description,duration=5000}:{open:boolean;onOpenChange:(open:boolean)=>void;title:string;description?:string;duration?:number}){
 return <RT.Provider swipeDirection="right" duration={duration}><RT.Root open={open} onOpenChange={onOpenChange} className="a-toast rounded-xl border border-line bg-card p-5 text-ink shadow-xl"><RT.Title className="font-medium">{title}</RT.Title>{description&&<RT.Description className="mt-1 text-sm text-muted">{description}</RT.Description>}<RT.Close className="mt-3 text-sm underline">Dismiss</RT.Close></RT.Root><RT.Viewport className="fixed bottom-4 right-4 z-[70] m-0 w-[min(360px,calc(100%-32px))] list-none outline-none"/></RT.Provider>
}
export function ToastDemo(){const [open,setOpen]=React.useState(false);return <><Button tone="outline" onClick={()=>setOpen(true)}>Show notification</Button><Toast open={open} onOpenChange={setOpen} title="Changes saved" description="Your local example has been updated."/></>}

import * as React from "react";
import { LoaderCircle } from "lucide-react";
import { cx } from "./utils";

export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  tone?: "primary" | "secondary" | "outline" | "quiet" | "danger" | "accent";
  size?: "sm" | "md" | "lg";
  loading?: boolean;
};

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      tone = "primary",
      size = "md",
      loading = false,
      disabled,
      children,
      className,
      type = "button",
      ...props
    },
    ref,
  ) {
    return (
      <button
        {...props}
        ref={ref}
        type={type}
        disabled={disabled || loading}
        aria-busy={loading ? true : props["aria-busy"]}
        className={cx(
          "a-button relative",
          {
            "bg-ink text-paper hover:bg-ink/85": tone === "primary",
            "bg-surface text-ink hover:bg-surface/70": tone === "secondary",
            "border border-control bg-transparent text-ink": tone === "outline",
            "bg-transparent text-ink hover:bg-surface": tone === "quiet",
            "bg-danger text-on-danger": tone === "danger",
            "bg-gold text-[#181818]": tone === "accent",
          },
          {
            "min-h-11 sm:min-h-9 px-3 py-2 text-xs": size === "sm",
            "min-h-11 px-4 py-2 text-sm": size === "md",
            "min-h-13 px-6 py-3 text-base": size === "lg",
          },
          loading && "disabled:opacity-100",
          className,
        )}
      >
        <span
          className="inline-flex min-w-0 items-center justify-center gap-2 [&_svg]:shrink-0"
          style={{ opacity: loading ? 0 : undefined }}
        >
          {children}
        </span>
        {loading && (
          <span
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 flex items-center justify-center"
          >
            <LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" />
          </span>
        )}
      </button>
    );
  },
);

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export const cx = (...values: ClassValue[]) => twMerge(clsx(values));

@import "tailwindcss";
@import "@fontsource-variable/dm-sans";
@import "@fontsource-variable/lora";
@import "./motion.css";
@import "./effects.css";
@source "./**/*.{ts,tsx}";
@theme {
  --default-transition-duration: 220ms;
  --default-transition-timing-function: cubic-bezier(.2, .7, .2, 1);
  --color-paper: #f4f1e9;
  --color-ink: #20201d;
  --color-muted: #656158;
  --color-line: #d2ccc0;
  --color-control: #898d80;
  --color-surface: #e8e3d8;
  --color-card: #faf8f2;
  --color-terracotta: #ac4333;
  --color-gold: #edbd52;
  --color-danger: #a32925;
  --color-on-danger: #ffffff;
  --color-success: #326145;
  --color-chart-3: #b4bdb0;
  --color-chart-4: #cfc5ad;
  --color-chart-5: #8b9fa2;
  --radius-lg: 9px;
  --radius-xl: 16px;
  --radius-2xl: 22px;
  --font-sans: "DM Sans Variable", Arial, sans-serif;
  --font-editorial: "Lora Variable", Georgia, serif;
}
@layer base {
  * {
    border-color: var(--color-line);
  }
  body {
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
    margin: 0;
    -webkit-font-smoothing: antialiased;
  }
  button:not(:disabled),
  summary {
    cursor: pointer;
  }
  :focus-visible {
    outline: 2px solid var(--color-terracotta);
    outline-offset: 4px;
  }
}
.a-scroll-track { width: 14px; padding: 16px 4px; background: transparent; touch-action: none; user-select: none; }
.a-scroll-thumb { min-height: 32px; border-radius: 999px; background: color-mix(in srgb, var(--color-muted) 32%, transparent); transition: background-color var(--motion-normal) var(--motion-ease); }
.a-scroll-track:hover .a-scroll-thumb, .a-scroll-thumb:active { background: color-mix(in srgb, var(--color-muted) 72%, transparent); }
/* Native scroll surfaces inside components share the ScrollArea thumb: a 6px pill on a transparent track. */
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar { width: 12px; height: 12px; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-track { background: transparent; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb { border: 3px solid transparent; border-radius: 999px; background: color-mix(in srgb, var(--color-muted) 32%, transparent); background-clip: padding-box; min-height: 32px; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb:hover, :is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb:active { background-color: color-mix(in srgb, var(--color-muted) 72%, transparent); }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-corner { background: transparent; }
@supports not selector(::-webkit-scrollbar) {
  :is(.a-scrollbar, .a-popup, .a-modal-content) { scrollbar-width: thin; scrollbar-color: color-mix(in srgb, var(--color-muted) 32%, transparent) transparent; }
}
@layer components {
  .a-card{
    padding:var(--space-card,24px);
    border:var(--card-border-width,1px) solid var(--color-card-border,var(--color-line));
    border-top-width:var(--card-top-width,1px);
    box-shadow:var(--shadow-card,none);
  }
  .a-button {
    @apply inline-flex shrink-0 items-center justify-center gap-2 rounded-lg font-medium transition-[background-color,color,border-color,box-shadow,transform] disabled:pointer-events-none disabled:opacity-45 focus-visible:outline-2 focus-visible:outline-offset-4 active:translate-y-px;
    letter-spacing: -0.015em;
    max-width: 100%;
    white-space: normal;
    overflow-wrap: anywhere;
  }
  .a-input {
    @apply min-h-10 w-full rounded-lg border border-line bg-paper/50 px-3 py-2 text-sm text-ink shadow-xs placeholder:text-muted/75 disabled:opacity-50 aria-invalid:border-danger focus-visible:bg-card transition-colors;
  }
  .a-overlay {
    @apply fixed inset-0 z-50 bg-black/40 backdrop-blur-xs;
  }
  .a-popup {
    @apply z-50 rounded-xl border border-line bg-card p-2 text-ink shadow-xl;
    max-width: calc(100vw - 24px);
    max-height: min(
      80dvh,
      var(--radix-popover-content-available-height, 80dvh)
    );
    overflow-y: auto;
    overscroll-behavior: contain;
    background: var(--color-menu, var(--color-card));
  }
}
.a-modal-content {
  overflow-wrap: anywhere;
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
.a-input {
  min-width: 0;
}
progress {
  appearance: none;
  height: 8px;
  background: var(--color-surface);
}
progress::-webkit-progress-bar {
  background: var(--color-surface);
  border-radius: 100px;
}
progress::-webkit-progress-value {
  background: var(--color-terracotta);
  border-radius: 100px;
}
progress::-moz-progress-bar {
  background: var(--color-terracotta);
  border-radius: 100px;
}
.a-calendar {
  --cal-radius: 10px;
  --cal-target: 44px;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
  color: var(--color-ink);
  width: 100%;
  max-width: 100%;
  --rdp-accent-color: var(--color-terracotta);
}
.a-calendar .rdp-months {
  display: flex;
  flex-wrap: wrap;
  gap: 32px;
  align-items: start;
}
.a-calendar .rdp-month {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  flex: 1 1 260px;
  min-width: 0;
  gap: 10px 8px;
  /* Zoomed text may need more than the parent width; the month then scrolls as a bounded region instead of overlapping digits. */
  overflow-x: auto;
}
.a-calendar .rdp-month_caption {
  flex: 1 1 auto;
  min-width: 0;
  padding-inline-start: 6px;
  font-family: var(--font-editorial);
  font-size: 1.125rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  overflow-wrap: break-word;
}
.a-calendar .rdp-caption_label {
  line-height: 1.4;
}
.a-calendar .rdp-nav {
  display: flex;
  gap: 6px;
  margin: 0;
  margin-inline-start: auto;
}
.a-calendar .rdp-month_grid {
  flex: 1 0 100%;
  border-collapse: separate;
  border-spacing: 0 2px;
  width: 100%;
  table-layout: auto;
}
.a-calendar th {
  width: 14.28%;
  min-width: 1.75em;
  height: 36px;
  color: var(--color-muted);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: center;
  white-space: nowrap;
}
.a-calendar td {
  width: 14.28%;
  min-width: 1.75em;
  height: var(--cal-target);
  padding: 0;
  text-align: center;
}
.a-calendar .rdp-week_number {
  width: auto;
  min-width: 1.5em;
  padding-inline-end: 6px;
  color: var(--color-muted);
  font-size: 0.6875rem;
  letter-spacing: 0.04em;
}
.a-calendar button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-width: 24px;
  min-height: var(--cal-target);
  border: 1px solid transparent;
  border-radius: var(--cal-radius);
  color: inherit;
  background: transparent;
  font: inherit;
  line-height: 1;
  touch-action: manipulation;
  transition:
    background-color var(--motion-fast, 140ms) var(--motion-ease, ease-out),
    color var(--motion-fast, 140ms) var(--motion-ease, ease-out),
    border-color var(--motion-fast, 140ms) var(--motion-ease, ease-out);
}
.a-calendar button:hover:not(:disabled):not([aria-disabled="true"]) {
  background: var(--color-surface);
}
.a-calendar button:focus-visible {
  outline-offset: -3px;
  z-index: 1;
}
.a-calendar [data-today="true"] button {
  font-weight: 600;
}
.a-calendar [data-today="true"] button::after {
  content: "";
  position: absolute;
  bottom: 6px;
  left: 50%;
  width: 4px;
  height: 4px;
  border-radius: 999px;
  background: var(--color-terracotta);
  translate: -50% 0;
}
.a-calendar [data-outside="true"] button {
  color: color-mix(in srgb, var(--color-muted) 65%, transparent);
}
.a-calendar [aria-selected="true"] button {
  background: var(--color-ink);
  color: var(--color-paper);
}
.a-calendar [aria-selected="true"] button::after {
  background: var(--color-paper);
}
.a-calendar [aria-selected="true"] button:hover:not(:disabled) {
  background: var(--color-ink);
}
.a-calendar .rdp-range_middle {
  background: var(--color-surface);
}
.a-calendar .rdp-range_middle button {
  background: transparent;
  color: var(--color-ink);
  border-radius: 0;
}
.a-calendar .rdp-range_middle button::after {
  background: var(--color-terracotta);
}
.a-calendar .rdp-range_middle button:hover:not(:disabled) {
  background: color-mix(in srgb, var(--color-ink) 8%, var(--color-surface));
}
.a-calendar .rdp-range_start:not(.rdp-range_end) {
  background: linear-gradient(to right, transparent 50%, var(--color-surface) 50%);
}
.a-calendar .rdp-range_end:not(.rdp-range_start) {
  background: linear-gradient(to left, transparent 50%, var(--color-surface) 50%);
}
.a-calendar[dir="rtl"] .rdp-range_start:not(.rdp-range_end) {
  background: linear-gradient(to left, transparent 50%, var(--color-surface) 50%);
}
.a-calendar[dir="rtl"] .rdp-range_end:not(.rdp-range_start) {
  background: linear-gradient(to right, transparent 50%, var(--color-surface) 50%);
}
.a-calendar tr > .rdp-range_middle:first-child,
.a-calendar tr > .rdp-week_number + .rdp-range_middle {
  border-start-start-radius: var(--cal-radius);
  border-end-start-radius: var(--cal-radius);
}
.a-calendar .rdp-hidden,
.a-calendar .rdp-hidden.rdp-range_start,
.a-calendar .rdp-hidden.rdp-range_middle,
.a-calendar .rdp-hidden.rdp-range_end {
  background: transparent;
}
.a-calendar tr > .rdp-range_middle:last-child {
  border-start-end-radius: var(--cal-radius);
  border-end-end-radius: var(--cal-radius);
}
.a-calendar button:disabled,
.a-calendar button[aria-disabled="true"] {
  color: var(--color-muted);
  opacity: 0.45;
  cursor: default;
}
.a-calendar .rdp-button_previous,
.a-calendar .rdp-button_next {
  width: 40px;
  height: 40px;
  min-height: 40px;
  border-color: var(--color-line);
  border-radius: 999px;
  color: var(--color-ink);
  flex-shrink: 0;
}
.a-calendar .rdp-button_previous:hover:not(:disabled),
.a-calendar .rdp-button_next:hover:not(:disabled) {
  border-color: var(--color-control);
  background: var(--color-card);
}
.a-calendar svg {
  width: 14px;
  height: 14px;
  fill: currentColor;
}
.a-calendar .rdp-dropdowns {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  align-items: center;
